function update(dt){
if(!started)return;
if(player.inCar){
 const forward=keys.w||keys.arrowup?1:keys.s||keys.arrowdown?-1:0;
 const turn=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0);
 car.speed+=(forward*240-car.speed)*dt*2.2;
 if(forward===0)car.speed*=Math.pow(.94,dt*60);
 car.speed=Math.max(-100,Math.min(260,car.speed));
 if(Math.abs(car.speed)>8)car.a+=turn*dt*(.018*Math.abs(car.speed)+.38)*(car.speed<0?-1:1);
 let nx=car.x+Math.sin(car.a)*car.speed*dt,ny=car.y-Math.cos(car.a)*car.speed*dt;
 if(!collides(nx,ny)){car.x=nx;car.y=ny}else{car.speed*=-.25;player.hp=Math.max(0,player.hp-2)}
 player.x=car.x;player.y=car.y;
 wantedTime+=wanted>0?dt:0;
 if(wantedTime>9){wantedTime=0;wanted=Math.max(0,wanted-1)}
}else{
 let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0);
 let dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0);
 let l=Math.hypot(dx,dy)||1;dx/=l;dy/=l;
 let nx=player.x+dx*145*dt,ny=player.y+dy*145*dt;
 if(!collides(nx,ny)){player.x=nx;player.y=ny}
 if(dx||dy)player.a=Math.atan2(dy,dx)+Math.PI/2;
}
for(const c of cars){
 if(c.ai){c.a+=Math.sin(performance.now*.0001+c.x)*.002;
 let nx=c.x+Math.sin(c.a)*c.speed*dt,ny=c.y-Math.cos(c.a)*c.speed*dt;
 if(!collides(nx,ny)){c.x=nx;c.y=ny}else c.a+=1.2}
}
for(const p of peds){
 p.a+=Math.sin(performance.now*.001+p.x)*.01;
 let nx=p.x+Math.sin(p.a)*p.speed*dt,ny=p.y-Math.cos(p.a)*p.speed*dt;
 if(!collides(nx,ny)){p.x=nx;p.y=ny}else p.a+=2;
}
updatePrompt();
document.getElementById('speedValue').textContent=Math.round(Math.abs(car.speed)*.58);
document.getElementById('health').style.width=player.hp+'%';
document.getElementById('wanted').textContent='★'.repeat(wanted)+'☆'.repeat(5-wanted);

